  "Hausa kingdoms": {capital:"No common capital; chief cities Kano, Katsina, Zaria (Zazzau), Daura and Alkalawa (Gobir)",founder:"Bagauda of Kano (traditionally); legendary ancestor Bayajidda",successor:"Sokoto Caliphate; Abuja, Maradi and Tsibiri successor states"},
  "Mombasa": {capital:"Mombasa (Mvita)",founder:"Unknown; traditionally the queen Mwana Mkisi and Shehe Mvita",successor:"Portuguese Mombasa"},
